  "La ritmul de acum se termină pe {date}, cu {days} înainte de salariu. Ca să ajungă: cel mult {safe} pe zi.": "At the current pace it runs out on {date}, {days} before payday. To make it last: at most {safe} a day.",
  "Spațiul de stocare al browserului este plin": "The browser's storage is full",
  "Aplicația nu a putut salva o preferință locală. Datele financiare rămân în stocarea principală (IndexedDB). Poți elibera cache-ul și reîncărca, exporta un backup din Setări sau șterge datele site-ului din setările browserului.": "The app couldn't save a local preference. Your financial data stays in the main storage (IndexedDB). You can free the cache and reload, export a backup from Settings, or clear the site data in your browser settings.",
  "Apasă „Eliberează cache și reîncarcă” (datele rămân).": "Tap “Free cache and reload” (your data stays).",
  "Dacă tot apare: Setări → exportă backup, apoi șterge datele site-ului.": "If it still shows: Settings → export a backup, then clear the site data.",
  "Chrome/Safari: Setări site → Stocare → Șterge datele.": "Chrome/Safari: Site settings → Storage → Clear data.",
