  "În ultimele 7 zile sunt {amount} RON, cu {increase} RON peste cele 7 zile anterioare. Compară intrările înainte de a decide dacă este un vârf punctual sau un nou ritm.": "The last 7 days come to {amount} RON, {increase} RON above the 7 days before. Compare the entries before deciding whether it is a one-off spike or a new pace.",
