  "Înregistrează câteva venituri și cheltuieli, apoi stabilește data următorului venit. Asistentul va compara istoricul, bilanțul și ritmul real fără să trimită datele către un serviciu extern.": "Record a few incomes and expenses, then set the date of your next payday. The assistant will compare your history, balance and real pace without sending the data to any external service.",
