  "Încă o sursă": "Another source",
  "Cumpărătură pentru toată luna": "Purchase for the whole month",
  "De pe bon, ce nu e mâncare: {items} = {amount}.": "From the receipt, what is not food: {items} = {amount}.",
  "Detergent, hrană pentru animale, provizii: se împart pe săptămânile rămase, nu golesc săptămâna asta.": "Detergent, pet food, supplies: spread over the remaining weeks instead of emptying this week.",
  "Din care pentru toată luna (lei)": "Of which for the whole month (lei)",
  "Gol = toată suma. Ex.: din bonul de 165,50, doar detergentul și hrana pisicii.": "Empty = the whole amount. E.g. from a 165.50 receipt, only the detergent and cat food.",
  "Se împarte pe cele {weeks} săptămâni rămase, după mărimea lor (o săptămână întreagă cam {full}). Săptămâna asta scade {now}.": "Spread over the {weeks} remaining weeks by their size (a full week about {full}). This week loses {now}.",
  "Pe {source} sunt liberi acum doar {free}. Scade suma completării sau alege altă sursă.": "{source} only has {free} free right now. Lower this part or pick another source.",
  "Dacă salariul sau tichetele n-au intrat încă, notează-le întâi ca venit: plicul se face din banii care chiar sunt.": "If the salary or meal vouchers have not arrived yet, record them as income first: an envelope is made from money that is really there.",
  "Plătit și din altă sursă": "Also paid from another source",
  "Salariul vine azi": "Salary comes today",
  "Ratele pe numele {names} ({amount}) nu se scad: pe sursele lor nu e notat niciun venit.": "Instalments of {names} ({amount}) are not deducted: no income is recorded on their sources.",
  "Când intră salariul, notează-l și lipsa dispare.": "When the salary arrives, record it and the shortfall goes away.",
  "Fără dată de salariu: arată doar câți bani am": "No payday: just show how much money I have",
  "Ai acum în surse": "In your sources now",
  "Până pe {date} sunt de plătit {dues} în rate și facturi: lipsesc {missing} până la venit.": "Until {date}, {dues} in instalments and bills are due: {missing} is missing until the next income.",
  "Prima: {name}, {amount}, pe {date}.": "First: {name}, {amount}, on {date}.",
  "Cifra mare e banii notați acum în surse. Dedesubt: cât lipsește ca să plătești ratele și facturile care cad până la următorul venit. Nu e o cheltuială făcută.": "The big figure is the money recorded in your sources now. Below: what is missing to pay the instalments and bills due before the next income. It is not money spent.",
  "Ratele pe numele {names} ({amount}) nu se scad din banii tăi: pe sursele lor nu e notat niciun venit. Le vezi și le confirmi în Obligații; dacă una se plătește din banii tăi, alege sursa ta la confirmare.": "Instalments in the name of {names} ({amount}) are not deducted from your money: no income is recorded on their sources. You see and confirm them in Obligations; if one is paid from your money, pick your source when confirming.",
  "Lipsesc pentru rate și facturi": "Short for instalments and bills",
  "Rate de acoperit": "Instalments to cover",
  "Până pe {date} sunt de plătit {dues} în rate și facturi, iar în surse ai {available}.": "Until {date} there are {dues} in instalments and bills to pay, and your sources hold {available}.",
  "Venitul acestui ciclu nu e notat încă: când intră salariul, notează-l ca venit și lipsa dispare.": "This cycle's income is not recorded yet: when the salary arrives, record it as income and the shortfall goes away.",
  "următorul venit": "the next income",
  "Nu e o cheltuială făcută. E cât lipsește ca să plătești ratele și facturile care cad până la următorul venit, cu banii notați acum în surse.": "This is not money spent. It is what is missing to pay the instalments and bills due before the next income, with the money currently recorded in your sources.",
  "LIPSESC": "MISSING",
  "Ai {available} în surse. Până la venit sunt de plătit {dues} în rate și facturi{envelopes}. Lipsesc {missing}; când notezi salariul, se acoperă.": "You have {available} in your sources. Until the next income, {dues} in instalments and bills are due{envelopes}. {missing} is missing; recording the salary covers it.",
  " și {amount} rămân în plicuri": " and {amount} remain in envelopes",
  "{available} disponibili = {placed} în plicuri + {dues} rate și facturi + {free} liberi · {percent}% așezat": "{available} available = {placed} in envelopes + {dues} instalments and bills + {free} free · {percent}% placed",
  "Planul are nevoie de o dată de salariu pentru a calcula ritmul sigur de cheltuire.": "The plan needs a payday to work out a safe spending pace.",
  "Planul are nevoie de următorul salariu ca să calculeze ritmul.": "The plan needs the next payday to work out the pace.",
  "Planul este depășit: suma arată cât trebuie acoperit, nu bani disponibili pentru cheltuieli.": "The plan is over: this figure shows what must be covered, not money available to spend.",
