  "Plicuri neconfigurate": "Envelopes not set up",
  "Ai acum": "You have now",
  "Cheltuit astăzi": "Spent today",
  "Soldul surselor, după mișcările de azi. Pune data venitului în Plicuri, sau, la venituri neregulate, câte zile să-ți ajungă banii, ca să vezi cât poți folosi pe zi.": "Your sources' balance after today's entries. Set your payday in Envelopes — or, with irregular income, how many days your money should last — to see what you can use per day.",
  "Nu e un sold. E suma ieșită azi, până pui un venit sau un plic.": "Not a balance. It is what went out today, until you add income or an envelope.",
  "Este soldul de pe card, cash sau bonuri, după ce ai înregistrat. Fără data venitului nu calculăm un ritm zilnic.": "This is the balance on card, cash or meal vouchers after what you recorded. Without a payday we do not compute a daily pace.",
