  "{amount} rămân după cheltuielile înregistrate și rezervele deja planificate.": "{amount} remain after recorded spending and reserves already planned.",
  "OBIECTIV COMUN": "SHARED GOAL",
  "Partea zilei: banii de la începutul zilei, după scadențe și rate, împărțiți pe zilele până la venit. Ce cheltui azi scade din ea; mâine restul se reîmparte. În plicuri mai sunt {envelopes}; în surse {sources}.": "Today's share: the money at the start of the day, after due payments and instalments, split over the days until payday. What you spend today comes out of it; tomorrow the rest is split again. Envelopes still hold {envelopes}; sources hold {sources}.",
  "Este ce mai poți folosi din plicurile alocate. Reperul zilnic împarte suma pe cele {days} zile până la venit — nu e bani în plus, e ritmul ca să nu golești plicurile înainte.": "It is what you can still use from allocated envelopes. The daily benchmark splits the amount across the {days} days until income — not extra money, the pace so you do not empty envelopes early.",
