  "Cuvinte scurte, fără confuzie": "Short words, without confusion",
  "Plic": "Envelope",
  "Nu e un cont bancar. E o limită pe care ți-o pui singur pentru o categorie (mâncare, transport). Banii stau în surse; plicul spune cât poți cheltui din ele pe acel scop.": "It is not a bank account. It is a limit you set yourself for a category (food, transport). Money stays in sources; the envelope says how much you can spend from them on that purpose.",
  "Reper": "Benchmark",
  "Nu e soldul din bancă. E ritmul zilei din plan — cât e prudent să folosești azi ca să ajungi la următorul venit fără să golești plicurile.": "It is not the bank balance. It is the day's pace from the plan — how much is prudent to use today so you reach the next income without emptying the envelopes.",
  "Unde stau banii reali: card, cash, bonuri de masă. Soldul se calculează aici.": "Where real money sits: card, cash, meal vouchers. The balance is calculated here.",
  "Ciclu": "Cycle",
  "De la începutul planului până la următorul salariu, nu neapărat luna calendaristică.": "From the start of the plan to the next payday, not necessarily the calendar month.",
  "Plic ≠ cont · Reper ≠ sold": "Envelope ≠ account · Benchmark ≠ balance",
  "Plicul e o limită pe categorie, nu un cont. Reperul e ritmul zilei din plan, nu soldul din bancă. Detalii în Ghid.": "An envelope is a category limit, not an account. The benchmark is the day's pace from the plan, not the bank balance. Details in the Guide.",
