  "Am identificat eventual categoria, dar nu și o sumă. Spune, de exemplu: „Dacă plătesc 120 lei pe taxi mâine”. Simularea nu adaugă nicio mișcare în registru.": "I may have found the category, but not an amount. Say, for example: \\u201eIf I spend 120 RON on a taxi tomorrow\\u201d. The simulation adds nothing to the ledger.",
  "Am marcat doar tipare care combină frecvența cu multe sume mici. Verifică-le cu contextul tău înainte să schimbi ceva.": "I have only flagged patterns that combine frequency with many small amounts. Check them against your own context before changing anything.",
  "Am nevoie doar de o sumă aproximativă. De exemplu: „salariul meu este 6.500 lei pe lună”.": "I only need a rough amount. For example: \\u00abmy salary is 6,500 RON a month\\u00bb.",
