  "Nu ai încă un curs salvat pentru această valută. Îl poți pune o dată, în Setări.": "You have no saved rate for this currency yet. You can set it once, in Settings.",
  "Nu ai înregistrat datorii. Adaugă o rată dacă vrei să fie rezervată în plan.": "You have no debts recorded. Add an instalment if you want it set aside in the plan.",
  "Nu am citit clar textul de pe bon. Scrie magazinul și totalul; fotografia rămâne atașată și poți salva fără produse separate.": "I could not read the receipt clearly. Write the shop and the total; the photo stays attached and you can save without separate items.",
  "Nu am găsit categoriile și sumele. Scrie simplu: „alimente 1500, facturi 800, transport 400, economii 500”.": "I could not find the categories and amounts. Write it plainly: \\u00abgroceries 1500, bills 800, transport 400, savings 500\\u00bb.",
  "Nu am putut citi fișierul. Încearcă din nou cu o fotografie clară a bonului.": "I could not read the file. Try again with a clear photo of the receipt.",
  "Nu am putut muta fotografiile vechi ale bonurilor; acestea nu au fost șterse.": "I could not move the old receipt photos; they have not been deleted.",
