  "Nu leagă telefoanele. E doar un semn în backup-ul exportat, ca să recunoști fișierul. Conectarea se face din Sync, cu invitația familiei.": "It doesn't link phones. It's just a mark in the exported backup so you recognise the file. Phones connect in Sync, with the family invitation.",
