  "Perfect, am notat venitul. Acum vreau să expunem toate obligațiile: ai credite, rate, carduri de cumpărături sau bani împrumutați? Spune-mi numele și soldul aproximativ. Dacă nu ai, spune doar „nu am datorii”.": "Good, I have noted the income. Now let's lay out every obligation: do you have loans, instalments, store cards or borrowed money? Tell me the name and the rough balance. If you have none, just say \\u00abno debts\\u00bb.",
