  "Spațiul local este aproape plin. Fotografiile bonurilor rămân în stocarea dedicată; exportă un backup dacă problema continuă.": "Local storage is nearly full. Receipt photos stay in their own store; export a backup if this continues.",
  "Spune-mi cât vrei să rezervi pentru fiecare zonă. Nu trebuie să fie perfect; ajustăm împreună.": "Tell me how much you want to set aside for each area. It does not have to be perfect; we adjust together.",
  "Spune-mi suma și ce ai plătit, de exemplu: „am cheltuit 50 de lei pe combustibil”.": "Tell me the amount and what you paid for, for example: \\u00abI spent 50 RON on fuel\\u00bb.",
  "Spune-mi, de exemplu: „Credit auto, mai am 18.000 lei” sau „rată la bancă, sold 42.000 lei”.": "Tell me, for example: \\u00abcar loan, 18,000 RON left\\u00bb or \\u00abbank instalment, balance 42,000 RON\\u00bb.",
  "Stocarea modernă nu este disponibilă; folosim fallback-ul local al browserului.": "The modern storage is not available; we are using the browser's local fallback.",
