  "Sunt aici cu tine și te ghidez pas cu pas. Începem cu veniturile: ce bani intră într-o lună obișnuită — salariu, pensie, freelancing sau alte venituri? Spune-mi suma și îți pun prima bază în aplicație.": "I am here with you and I will guide you step by step. Let's start with income: what money comes in during an ordinary month — salary, pension, freelance work or something else? Tell me the amount and I will lay the first foundation in the app.",
  "Sunt aici cu tine. Poți să-mi scrii orice mișcare în cuvintele tale, iar eu o verific înainte să o salvez.": "I am here with you. Write any movement in your own words and I will check it before saving.",
