  "În regulă, fără datorii. Acum împărțim venitul pe categorii: alimente, facturi, transport și economii. Ce sume vrei să rezervi?": "All right, no debts. Now let's share the income across categories: groceries, bills, transport and savings. What amounts do you want to set aside?",
  "În regulă, lăsăm rata de completat mai târziu. Acum împărțim venitul pe categorii: alimente, facturi, transport și economii.": "All right, we will fill in the instalment later. Now let's share the income across categories: groceries, bills, transport and savings.",
