  "În Setări → Membri poți marca un membru drept copil. Dă-i apoi un plic pe numele lui, în Plicuri, iar aici va vedea cât mai are din banii de buzunar.": "In Settings → Members you can mark someone as a child. Then give them an envelope in their name, in Envelopes, and here they will see how much pocket money is left.",
  "Începem cu situația ta de acum. La fiecare pas îți explic ce înseamnă cifra și îți cer confirmarea înainte de orice schimbare.": "We start from where you are now. At each step I explain what the number means and ask you to confirm before anything changes.",
