  "Când îți vine salariul (în jur de {date}), notează-l și îți propun împărțirea pe plicuri, după cele {count} cheltuieli declarate.": "When your salary comes in (around {date}), add it and I will propose how to split it into envelopes, based on the {count} expenses you declared.",
  "Când îți vine salariul, notează-l și îți propun împărțirea pe plicuri, după cele {count} cheltuieli declarate.": "When your salary comes in, add it and I will propose how to split it into envelopes, based on the {count} expenses you declared.",
  "Notează salariul": "Add your salary",
  "Venitul de azi e pentru ciclul următor: repartizează-l în plicuri. Cifra zilei vine din banii ciclului care se încheie.": "Today's income is for the next cycle: split it into envelopes. Today's figure comes from the money of the cycle that is ending.",
