  "Nu am putut porni modul.": "Could not start the mode.",
  "Un singur ecran, cu text mare: cât are azi persoana din plicurile ei (de exemplu „Bani de buzunar”) și un buton de notat. Nu se văd restul bugetului, sincronizarea sau copiile de siguranță. Ieșirea cere codul ales acum.": "One screen with large text: what the person has today from their own envelopes (e.g. “Pocket money”) and a button to record. The rest of the budget, sync and backups are hidden. Leaving requires the code chosen now.",
