  "COPIE DE SIGURANȚĂ": "BACKUP",
  "Păstrez o copie săptămânală?": "Keep a weekly backup?",
  "O dată pe săptămână pun un fișier cu datele în Descărcări. Dacă se strică telefonul, îl încarci din Setări → „Alege backup”. Fișierul are sumele în clar: nu-l trimite nimănui.": "Once a week I put a file with your data in Downloads. If the phone breaks, load it from Settings → “Choose backup”. The file has the amounts in plain text: don't send it to anyone.",
  "În browser nu pot salva singur: o dată pe săptămână îți amintesc să descarci copia. Dacă pierzi datele, o încarci din Setări → „Alege backup”.": "In the browser I can't save on my own: once a week I'll remind you to download the backup. If you lose your data, load it from Settings → “Choose backup”.",
