  "Bifează ce aveți și scrie cam cât. Mâncarea e pe săptămână. Intervalele (300–400) le poți pune după, în Plicuri.": "Tick what you have and write roughly how much. Food is per week. Ranges (300–400) can be added later, in Envelopes.",
