  "mereu în aceeași zi?": "on the same day?",
  "Următorul: ~{date}. Dacă poate veni cu câteva zile mai devreme sau mai târziu, plicurile se socotesc să ajungă și atunci.": "Next one: ~{date}. If it can arrive a few days earlier or later, envelopes are counted to last then too.",
  "Gata. Când notezi salariul, pe Astăzi apare propunerea: cât merge în fiecare plic. Nimic nu se mută fără să apeși „Aplică”.": "Done. When you record the salary, Today shows the split: how much goes into each envelope. Nothing moves until you tap “Apply”.",
