  "Cum scrii suma": "How you enter the amount",
  "{total} pentru zilele rămase, din care {fair} în săptămâna începută.": "{total} for the remaining days, of which {fair} in the started week.",
  "≈{weekly} pe săptămână întreagă, {fair} pentru zilele rămase din săptămâna începută.": "≈{weekly} per full week, {fair} for the remaining days of the started week.",
  "Alocă de azi, nu și pe zilele trecute": "Allocate from today, not for days already gone",
  "Săptămâna e începută: tranșa curentă primește doar partea zilelor rămase, iar restul pleacă în săptămânile următoare. Fără asta, zilele deja trecute rămân cu bani pe hârtie.": "The week is already under way: the current tranche only gets the share of its remaining days, and the rest moves into the following weeks. Without this, days already gone keep money on paper.",
  "Cum împarți cei {amount} nerepartizați": "How to split the {amount} unallocated",
  "Cum împarți cei {amount} din acest plic": "How to split the {amount} in this envelope",
