  "Nu mai sunt bani liberi în nicio sursă. Scade suma plicului.": "No source has free money left. Lower the envelope amount.",
  "O completare cere mai mult decât are sursa liberă. Scade suma sau alege altă sursă.": "A top-up asks for more than its source has free. Lower it or pick another source.",
  "Mai lipsesc {amount}. Completează din altă sursă mai jos sau scade suma plicului.": "{amount} short. Top up from another source below, or lower the envelope amount.",
  "Mai lipsesc {amount} și nu mai sunt bani liberi în nicio sursă. Scade suma plicului.": "{amount} short and no source has free money left. Lower the envelope amount.",
  "De azi, egal pe zile": "From today, equal per day",
  "Egal pe toată perioada": "Equal across the whole period",
  "Săptămâna începută rămâne întreagă": "The started week keeps a full budget",
  "{days} rămase din S{index} primesc {fair}, apoi {weekly} pe săptămână întreagă — ≈{perDay} pe zi peste tot.": "{days} left in W{index} get {fair}, then {weekly} per full week — ≈{perDay} a day throughout.",
  "{weekly} pe fiecare săptămână întreagă, ≈{perDay} pe zi.": "{weekly} for every full week, ≈{perDay} a day.",
  "S{index} păstrează {amount} pentru {days} rămase, apoi {weekly} pe săptămână — mai lejer acum, mai strâns până la venit.": "W{index} keeps {amount} for its {days} left, then {weekly} a week — easier now, tighter until payday.",
  "Suma trece peste cei {amount} rămași de repartizat. Scade-o sau eliberează bani dintr-un alt plic.": "The amount goes past the {amount} left to allocate. Lower it or free money from another envelope.",
