  "Crăciunul nu vine prin surprindere": "Christmas never arrives by surprise",
  "Scrii ce urmează în calendar și cât crezi că va costa. Aplicația îți spune cât să pui deoparte pe lună ca suma să fie gata la timp. Banii puși deoparte sunt o notă de planificare — nu pleacă din surse și nu intră în registru.": "Write down what the calendar holds and what you think it will cost. The app tells you how much to set aside each month so the money is ready in time. What you set aside is a planning note — it never leaves your sources and never enters the ledger.",
  "Fondul de evenimente": "The events fund",
