  "Începe cu Crăciunul sau cu o aniversare din familie — o atingere pe una dintre sugestiile de mai sus.": "Start with Christmas or a birthday in the family — one tap on a suggestion above.",
  "Toate evenimentele sunt mai departe de un an.": "Every event is more than a year away.",
  "Fondul de evenimente este o socoteală, nu un cont. Când vine ziua, cheltuiala se notează normal în registru.": "The events fund is a calculation, not an account. When the day comes, the expense is written in the ledger as usual.",
