  "Crăciun, Paște, aniversări — cu costul lor": "Christmas, Easter, birthdays — with their cost",
  "Evenimente viitoare și costul lor": "Upcoming events and what they cost",
  "Atenție: plicurile cer {missing} peste banii pe care îi văd ({free}). Spune-mi unde sunt banii — „am {missing} în card” — sau scade plicul.": "Careful: the envelopes ask for {missing} more than the money I can see ({free}). Tell me where the money is — “I have {missing} on the card” — or lower the envelope.",
  "Ciclul s-a încheiat pe {date} — pornește ciclul nou ca să-ți spun din nou ritmul zilei.": "The cycle ended on {date} — start the new one and I can give you the daily pace again.",
  " Scadențele rezervate ({amount}) rămân deoparte.": " The reserved bills ({amount}) stay out of it.",
  "după cum ai împărțit și până acum": "the way you have split it so far",
  "după cheltuielile tale din ultimele 90 de zile": "based on what you spent over the last 90 days",
  "Gata. Banii sunt în Mișcări ca intrare, iar soldul arată acum cât ai spus.": "Done. The money is in Movements as an entry, and the balance now shows what you said.",
  "Bani disponibili": "Money on hand",
  "Unde sunt banii?": "Where is the money?",
  "Îi trec pe „{name}”.": "I will record it on “{name}”.",
  "Atinge locul lor; altfel îi trec pe „{name}”.": "Tap where it is; otherwise I put it on “{name}”.",
  "Din ce zi sunt banii?": "From which day is the money?",
  "Dacă banii sunt de ieri sau de acum trei zile, alege ziua — altfel îi trec pe azi.": "If the money is from yesterday or three days ago, pick the day — otherwise I record it today.",
  "CICLUL S-A ÎNCHEIAT": "THE CYCLE HAS ENDED",
  "Ai cheltuit {spent} și au rămas {left} în plicuri.": "You spent {spent} and {left} is left in the envelopes.",
