  "{from} dă {amount} către {to}.": "{from} gives {amount} to {to}.",
  "Ați echilibrat pe {date} — de atunci sunteți chit": "You settled up on {date} — you have been even since",
  "Am echilibrat": "We settled up",
  "Alege portofelul fiecăruia — altfel banii se anulează pe același card.": "Pick each person's wallet — otherwise the money cancels out on the same card.",
  "Alege": "Choose",
  "Din portofelul lui {name}": "From {name}'s wallet",
  "În portofelul lui {name}": "Into {name}'s wallet",
  "Se trec două mișcări: iese din {from}, intră în {to}. Socoteala repornește de azi.": "Two movements are recorded: out of {from}, into {to}. The count restarts today.",
  "Alege două portofele diferite ca banii să treacă de la unul la altul.": "Pick two different wallets so the money actually moves from one person to the other.",
  "Uită": "Forget",
  "Ciclul se închide. Uită-te ce a rămas.": "The cycle is closing. Look at what is left.",
  "{name} e acum {amount}, ca în portofel.": "{name} is now {amount}, as in the wallet.",
  "Se trec două mișcări personale — una care iese, una care intră — și socoteala repornește de azi.": "Two personal movements are recorded — one out, one in — and the count restarts today.",
  "Sunteți chit. Nu e nimic de echilibrat.": "You are even. Nothing to settle.",
  "Decontare către {name}": "Settlement to {name}",
  "Decontare de la {name}": "Settlement from {name}",
  "CE AM ÎNVĂȚAT DE LA TINE": "WHAT I LEARNED FROM YOU",
  "Regulile după care îți propun.": "The rules behind my suggestions.",
  "Regulile scrise se sincronizează între telefoane. Obiceiurile se învață din alegerile tale și rămân pe telefonul ăsta. Nimic nu se salvează singur — toate sunt doar propuneri.": "Written rules sync between phones. Habits are learned from your choices and stay on this phone. Nothing saves itself — these are only suggestions.",
  "Încă nu am învățat nimic": "I have not learned anything yet",
  "După câteva cheltuieli trecute la fel, o să-ți propun singur plicul și sursa. Poți scrie și o regulă din ghid: „de fiecare dată când scriu Lidl, pune-l pe Alimente”.": "After a few expenses recorded the same way, I will suggest the envelope and the source myself. You can also write a rule in the guide: “whenever I write Lidl, put it on Groceries”.",
  "regulă scrisă de tine": "rule written by you",
  "ales de {count} ori, ultima dată {when}": "chosen {count} times, last on {when}",
  "Uită „{name}”": "Forget “{name}”",
  "Ce am învățat": "What I learned",
  "regulile după care îți propun": "the rules behind my suggestions",
  "ai cheltuit în medie {amount} pe ciclu, din {budget}": "you spent {amount} per cycle on average, out of {budget}",
  "ai cheltuit în medie {amount} pe ciclu, peste plicul de {budget}": "you spent {amount} per cycle on average, over the {budget} envelope",
  "Se aplică o schimbare de plic; mișcările rămân neatinse.": "One envelope change will be applied; movements stay untouched.",
  "Începe ciclul {start} – {end}": "Start the {start} – {end} cycle",
  "Se aplică {count} schimbări de plicuri; mișcările rămân neatinse.": "{count} envelope changes will be applied; movements stay untouched.",
  "Plicurile rămân cum sunt; mișcările rămân neatinse.": "Envelopes stay as they are; movements stay untouched.",
  "Ciclul s-a încheiat — vezi ce a rămas": "The cycle has ended — see what is left",
  "Cât ai de fapt pe „{name}”?": "How much do you actually have on “{name}”?",
  "Eu zic {amount}. {why}": "I say {amount}. {why}",
