  "Dobânda o găsești în contract (DAE sau dobânda anuală). Cu ea calculăm câte rate mai sunt, cât plătești în total și ce datorie merită închisă întâi.": "You'll find the interest in the contract (APR or annual rate). With it we work out how many instalments are left, what you'll pay in total and which debt to close first.",
