  "Rata de {monthly} nu acoperă nici dobânda lunară: datoria crește. Mărește rata sau vorbește cu creditorul.": "An instalment of {monthly} doesn't even cover the monthly interest: the debt is growing. Raise the instalment or talk to the lender.",
