  "lei (RON)": "lei (RON)",
  "Am venituri neregulate (PFA, freelancer)": "My income is irregular (freelancer)",
  "Fără dată de salariu: alegi câte zile trebuie să-ți ajungă banii, iar cifra zilei e banii de acum împărțiți pe atâtea zile.": "No payday: you choose how many days your money has to last, and today's figure is your money now split over those days.",
