  "Restaurează abonamentul": "Restore subscription",
  "Verificarea abonamentului nu a răspuns. Încearcă din nou.": "The subscription check didn't respond. Try again.",
  "Abonamentele nu sunt încă active. În perioada de testare, Familia e deschisă pentru toți.": "Subscriptions aren't live yet. During testing, Family is open to everyone.",
  "Abonamentul se cumpără din aplicația de pe Android (Google Play).": "The subscription is bought from the Android app (Google Play).",
  "Google Play nu a trimis confirmarea cumpărării.": "Google Play didn't send the purchase confirmation.",
  "Familia e activă. Mulțumim!": "Family is active. Thank you!",
