  "Plicurile propuse sunt o parte din venit: 25% mâncare, 8% transport, 20% casă și facturi. Le schimbi oricând în Plicuri.": "Suggested envelopes are a share of income: 25% food, 8% transport, 20% home and bills. Change them any time in Envelopes.",
