  "TESTARE": "TESTING",
  "Scrie ce ai făcut și ce s-a întâmplat. Nu trimitem sume, nume sau alte date din registru.": "Write what you did and what happened. We don't send amounts, names or other ledger data.",
  "Tipul mesajului": "Message type",
  "Nu merge ceva": "Something's broken",
