  "ex. Am notat 50 lei la benzină, iar pe Astăzi cifra nu s-a schimbat.": "e.g. I logged 50 lei for fuel, and the figure on Today didn't change.",
  "Cum te putem contacta (opțional)": "How can we reach you (optional)",
  "e-mail sau telefon": "email or phone",
  "Adaugă detalii tehnice: versiunea aplicației, ecranul, tipul telefonului și tema. Ne ajută să găsim problema.": "Add technical details: app version, screen, phone type and theme. It helps us find the problem.",
  "Se trimite…": "Sending…",
