  "Scrie câteva cuvinte despre ce s-a întâmplat.": "Write a few words about what happened.",
  "Mulțumim! Am primit mesajul.": "Thanks! We got your message.",
  "Nu e internet acum. Mesajul pleacă singur la următoarea deschidere a aplicației.": "No internet right now. The message will be sent automatically next time you open the app.",
  "Mesajul nu a putut fi trimis.": "The message couldn't be sent.",
  "Plicul săptămânii s-a terminat până {until}. În Plicuri mai ai {free} nerepartizați: poți pune o parte în plic.": "This week's envelope is used up until {until}. Envelopes still have {free} unassigned: you can move some into the envelope.",
  "Plicul săptămânii s-a terminat până {until}. Banii săptămânii următoare vin atunci.": "This week's envelope is empty until {until}. Next week's money starts then.",
  "Pune bani în plic": "Add money to the envelope",
