  "Setează în Plan": "Set it in Plan",
  "Ciclul de salariu are nevoie de data venitului": "The pay cycle needs your payday",
  "Spune în Plicuri când vine salariul; apoi comparația merge de la un salariu la altul, nu pe luna calendaristică.": "Set your payday in Envelopes; then the comparison runs from one payday to the next instead of the calendar month.",
  "Setează data salariului": "Set payday",
