  "Mutat din {name}": "Moved from {name}",
  "Ai o singură sursă de bani. Adaugă cash sau alt card în Setări ca să poți muta bani între ele.": "You have a single money source. Add cash or another card in Settings to move money between them.",
  "Nu e o cheltuială: banii trec dintr-un loc în altul. Plicurile și analiza rămân la fel.": "It is not spending: the money just moves from one place to another. Envelopes and analysis stay the same.",
  "Mută banii": "Move the money",
