  "SALARIUL": "SALARY",
  "Când vine salariul": "When the salary comes",
  "Data dă ritmul săptămânal al plicurilor. Poate varia cu câteva zile.": "The date sets the weekly pace of the envelopes. It can vary by a few days.",
  "Închizi anul {year}? Cele {count} mișcări se descarcă într-un fișier și ies din aplicație și din sincronizare, pe toate telefoanele. Soldurile rămân aceleași, iar în Setări rămâne rezumatul pe luni.": "Close {year}? The {count} movements are downloaded to a file and leave the app and sync, on every phone. Balances stay the same, and a monthly summary stays in Settings.",
  "Arhiva nu a putut fi salvată, așa că anul a rămas deschis. Încearcă din nou.": "The archive could not be saved, so the year stays open. Try again.",
  "Anul {year} e închis. Arhiva e în fișierul buget-familie-arhiva-{year}.json.": "{year} is closed. The archive is in the file buget-familie-arhiva-{year}.json.",
  "ANII ÎNCHEIAȚI": "PAST YEARS",
  "Închide anul": "Close the year",
  "Mișcările unui an încheiat trec într-un fișier de arhivă. Aplicația rămâne rapidă, iar sincronizarea nu se umple.": "A finished year's movements move into an archive file. The app stays fast and sync does not fill up.",
  "Închide anul {year}": "Close {year}",
  "{count} mișcări · intrat {income} · ieșit {expense}": "{count} movements · in {income} · out {expense}",
  "Anul {year} se poate închide după ce începe primul ciclu de salariu din {next}: ciclul curent are încă mișcări din decembrie.": "{year} can be closed once the first pay cycle of {next} starts: the current cycle still has December transactions.",
  "Fișierul e arhiva unui an închis, nu un backup. Îl deschizi din Setări → Copii de siguranță → Închide anul → „Vezi o arhivă”.": "This file is the archive of a closed year, not a backup. Open it from Settings → Backups → Close the year → “View an archive”.",
  "Fișierul nu e o arhivă de an Buget Familie.": "This file is not a Buget Familie year archive.",
  "Vezi o arhivă": "View an archive",
  "Arhiva {year}: {count} mișcări, doar pentru citit.": "Archive {year}: {count} transactions, read-only.",
  "Caută în arhivă": "Search the archive",
  "{count} rezultate · ieșit {amount}": "{count} results · out {amount}",
  "Nu am putut ajunge la camera familiei. Încerc din nou singur.": "Couldn't reach the family room. Retrying on my own.",
