  "{label} din {date} a intrat deja și e în suma de mai sus": "{label} from {date} already came in and is in the amount above",
  "Cheltuit înainte de aplicație": "Spent before the app",
  "Plicurile mai așteaptă {amount}: se acoperă când vine {label} pe {date}.": "Envelopes are still waiting for {amount}: covered when {label} arrives on {date}.",
  "Ai notat deja „{title}” · {amount} acum câteva secunde. Îl mai pun o dată?": "You already logged “{title}” · {amount} a few seconds ago. Log it again?",
  "Telefonul nu are internet acum. Încearcă din nou când are semnal; ce notezi rămâne pe telefon.": "The phone has no internet right now. Try again when it has signal; what you log stays on the phone.",
  "Semnalează răspunsul": "Report this answer",
  "Semnalat. Mulțumim!": "Reported. Thank you!",
  "Semnalezi acest răspuns al ghidului ca greșit sau nepotrivit? Trimitem doar textul răspunsului, fără datele familiei.": "Report this guide answer as wrong or inappropriate? We send only the answer text, without your family's data.",
  "Răspuns al ghidului AI semnalat": "Reported AI guide answer",
  "Plicuri fără limită": "Unlimited envelopes",
  "Doi oameni, un telefon": "Two people, one phone",
  "Pe {source} mai sunt liberi {free} (din {balance}, {reserved} sunt deja în plicuri sau scadențe).": "{free} is still free on {source} (of {balance}, {reserved} is already in envelopes or bills).",
  "Pune data salariului (Plicuri → Salariul) ca să vezi ritmul săptămânal.": "Set your payday (Envelopes → Salary) to see the weekly pace.",
  "Anul {year} e închis. Mișcarea intră în registrul de acum și în sold, nu în arhiva descărcată.": "{year} is closed. This movement goes into the current ledger and the balance, not into the downloaded archive.",
  "Un plic e o limită pe o categorie: Mâncare, Transport, Chirie. Începe cu unul, restul le adaugi când ai nevoie.": "An envelope is a limit for one category: Food, Transport, Rent. Start with one and add the rest when you need them.",
  "Backup restaurat: {moves} mișcări, {envelopes} plicuri, {members} membri.": "Backup restored: {moves} movements, {envelopes} envelopes, {members} members.",
  "Backup unit cu familia. Ce lipsea a fost adăugat.": "Backup merged with the family. What was missing has been added.",
  "Browserul a refuzat notificările. Le pornești din lacătul de lângă adresă → Notificări → Permite, apoi apeși din nou aici.": "The browser blocked notifications. Turn them on from the padlock next to the address → Notifications → Allow, then tap here again.",
  "Nu merge cu sumă variabilă: suma exactă e cea de pe factură, așa că plata o confirmi tu, cu un singur buton.": "Not available for a variable amount: the exact sum is on the bill, so you confirm the payment yourself with one tap.",
  "Fără internet nu se poate intra în familie. Butonul pornește singur când revine conexiunea.": "You can't join a family without internet. The button turns on by itself when the connection is back.",
