  "M-am uitat la luna aceasta: ai {expense} cheltuieli și {income} venituri. Nu te judec — hai să vedem împreună ce ajustăm.": "I looked at this month: {expense} in expenses and {income} in income. No judgement — let's see together what to adjust.",
  "Sunt cu tine în tabloul de azi. Spune-mi ce vrei să înțelegi sau să schimbi.": "I'm here with you on today's overview. Tell me what you'd like to understand or change.",
  "Sunt cu tine în secțiunea deschisă. Spune-mi ce vrei să înțelegi sau să schimbi.": "I'm here with you in this section. Tell me what you'd like to understand or change.",
  "Am șters **{title}**, {amount}.": "Deleted **{title}**, {amount}.",
