  "Am mutat {amount} din **{from}** în **{to}**.": "Moved {amount} from **{from}** to **{to}**.",
  "Am notat {amount} ca venit lunar. Următoarea întrebare: ai datorii, credite, rate sau carduri de cumpărături?": "I've noted {amount} as monthly income. Next question: do you have debts, loans, instalments or store cards?",
  "Am trecut „{name}” cu soldul de {amount}. Cât plătești lunar pentru această datorie?": "I've added “{name}” with a balance of {amount}. How much do you pay on it each month?",
  "Am notat rata de {amount}. Acum împărțim venitul pe categorii: alimente, facturi, transport și economii.": "I've noted the {amount} instalment. Now let's split the income by category: groceries, bills, transport and savings.",
  "Am repartizat {list}. Putem ajusta orice sumă. De acum sunt disponibil să urmărim împreună cheltuielile, veniturile și ritmul lunii.": "I've assigned {list}. We can adjust any amount. From now on I can help you follow spending, income and the month's pace.",
  "Ghidul fără internet înțelege doar româna. Conectează-te la internet ca să primești răspunsuri în engleză.": "The offline guide only understands Romanian. Connect to the internet to get answers in English.",
