  "Până la venit sunt {days} zile. {label}, media prudentă este {figure} RON pe zi: {amount} ÷ {days} zile. Calculul folosește {source} și nu modifică datele.": "There are {days} days until payday. {label}, the safe average is {figure} RON a day: {amount} ÷ {days} days. The calculation uses {source} and doesn't change your data.",
  "Media orientativă este {figure} RON pe zi {label}: {amount} ÷ {days}. Calculul folosește {source} și nu modifică planul.": "The rough average is {figure} RON a day {label}: {amount} ÷ {days}. The calculation uses {source} and doesn't change the plan.",
  "Ratele lunare însumează {rates}, iar datoria rămasă este {remaining}. Cea mai mare obligație este {name}. Acestea devin cheltuieli în registru numai când confirmi plata.": "Monthly instalments total {rates} and the remaining debt is {remaining}. The largest obligation is {name}. They become expenses in the ledger only when you confirm the payment.",
  "Poziția lichidă netă este {net}: solduri utilizabile {liquid} minus datorii rămase {debt}. Fluxul planului este {cashflow}, iar economiile urmărite sunt afișate separat: {savings}.": "Your net liquid position is {net}: usable balances {liquid} minus remaining debts {debt}. The plan's cash flow is {cashflow}; tracked savings are shown separately: {savings}.",
  "Cheltuielile înregistrate au un ritm de {pace} pe zi. Dacă ritmul se păstrează, până la {date} ar rămâne {left} după rezerve. Ritmul sigur, din planul curent, este {safe} pe zi.": "Recorded spending runs at {pace} a day. At this pace, by {date} you'd have {left} left after reserves. The safe pace from the current plan is {safe} a day.",
  "În perioada activă, {category} este categoria principală: {amount}. Răspunsul folosește mișcările dintre {from} și {to}.": "In the active period, {category} is the top category: {amount}. The answer uses movements between {from} and {to}.",
