  "Planul are {budget} disponibili, {spent} cheltuiți și {left} rămași până la următorul venit. Limita curentă este {weekly} pe săptămână.": "The plan has {budget} available, {spent} spent and {left} left until the next income. The current limit is {weekly} a week.",
