  "Luptătorii": "The Fighters",
  "Ați dat datoriilor o bucată mare din an. Fiecare rată plătită e libertate câștigată.": "You gave debts a big part of the year. Every payment is freedom earned.",
  "Constanții": "The Steady Ones",
  "Ați notat zi de zi, săptămâni la rând. Așa se vede cu adevărat unde merg banii.": "You logged day after day, for weeks. That's how you really see where money goes.",
  "Minimaliștii": "The Minimalists",
  "Multe zile fără niciun leu cheltuit. Liniștea asta se adună.": "Many days without spending a single leu. That calm adds up.",
  "Fidelii": "The Loyal Ones",
  "Aveți locurile voastre și vă întoarceți la ele. Acolo merită urmărite prețurile.": "You have your places and you keep going back. That's where prices are worth watching.",
  "Exploratorii": "The Explorers",
  "Un an în care ați învățat cum se mișcă banii familiei. Anul viitor porniți cu avans.": "A year of learning how the family's money moves. Next year you start ahead.",
