  "Povestea anului, refăcută: merge singură, cifrele numără, anul lună cu lună și personalitatea familiei.": "The year's story, redone: it plays on its own, numbers count up, the year month by month and the family's personality.",
  "Tendințe și obiceiuri: ce crește, ce scade, ziua cea mai scumpă, magazinele de bază și abonamentele uitate.": "Trends and habits: what's rising, what's falling, the priciest day, go-to stores and forgotten subscriptions.",
  "Calendarul banilor: luna ca o hartă de culori, cu facturile și soldul estimat pe zilele care vin.": "Money calendar: the month as a color map, with bills and the estimated balance for the days ahead.",
  "Simulator de investiții și pensie: dobândă compusă, inflație și cât să puneți deoparte lunar.": "Investment and retirement simulator: compound interest, inflation and how much to set aside each month.",
