  "Scrie una din sume; cealaltă se completează din total ({total}).": "Type one of the amounts; the other is filled in from the total ({total}).",
  "INSTRUMENTE AVANSATE": "ADVANCED TOOLS",
  "· grafice, tendințe, plan pe un an, investiții": "· charts, trends, one-year plan, investments",
  "Notat în Buget Familie, caietul de buget al casei. Nu e aplicație de plăți și nu cere date bancare.": "Logged in Buget Familie, the household budget notebook. It is not a payment app and asks for no bank details.",
  "Nu e o aplicație de plăți: nu mută bani și nu cere card, cont sau parola băncii. E caietul vostru de buget: notați voi, pe telefon.": "Not a payment app: it moves no money and asks for no card, account or bank password. It is your budget notebook: you log everything yourselves, on the phone.",
  "Nu e o aplicație de plăți și nici de monitorizare.": "Not a payment app, and not a tracking app either.",
  "Nu mută bani, nu se leagă de bancă și nu urmărește pe nimeni. E caietul de buget al familiei: vedeți doar ce notați voi.": "It moves no money, does not connect to your bank and tracks no one. It is the family budget notebook: you only see what you log.",
  "Instrumente avansate": "Advanced tools",
  "grafice, tendințe, plan pe un an, investiții, prețuri": "charts, trends, one-year plan, investments, prices",
  "Actualizează aplicația ca să folosești salvarea automată.": "Update the app to use automatic saving.",
  "Salvarea automată a eșuat.": "Automatic saving failed.",
  "Salvare automată la fiecare modificare": "Automatic save after every change",
  "Fișierul {file} din Documente/Buget Familie se rescrie singur la câteva secunde după fiecare schimbare. Îl imporți oricând din Backup.": "The file {file} in Documents/Buget Familie is rewritten a few seconds after every change. Import it any time from Backup.",
  "Doar în aplicația de pe telefon: browserul nu poate scrie singur fișiere.": "Only in the phone app: the browser cannot write files on its own.",
  "Ultima salvare: {time}.": "Last save: {time}.",
  "N-a mers ultima salvare: {reason}": "The last save failed: {reason}",
  "Ca să citească bonul, poza pleacă la un serviciu AI (Google Gemini sau Anthropic Claude), care scoate din ea produsele și sumele. Poza nu se păstrează: nici pe telefon, nici pe serverul nostru. Restul bugetului rămâne pe telefon.": "To read the receipt, the photo is sent to an AI service (Google Gemini or Anthropic Claude), which extracts the products and amounts. The photo is not kept: not on the phone, not on our server. The rest of your budget stays on the phone.",
  "Scanarea bonului": "Receipt scanning",
  "Am înțeles, scanez": "Got it, scan",
  "Nu am putut citi bonul acum. Mai încearcă o dată.": "We couldn't read the receipt right now. Please try again.",
  "Citesc bonul… durează câteva secunde.": "Reading the receipt… this takes a few seconds.",
  "Scanează bonul": "Scan receipt",
  "Toate produsele, pe categorii": "Every product, by category",
  "Bonurile scanate sau scrise de mână intră aici pe articole, grupe de marfă, alimente și nealimentare.": "Scanned or hand-written receipts land here by item, product group, food and non-food.",
  "Nu sunt articole pe perioada asta. Scanează un bon din Notează.": "No items in this period. Scan a receipt from Log.",
  "Articolele fac {items} lei, iar totalul bonului e {total} lei. Verifică rândurile înainte să salvezi.": "The items add up to {items} lei, but the receipt total is {total} lei. Check the lines before saving.",
  "Poza a fost greu de citit. Verifică sumele cu bonul în mână.": "The photo was hard to read. Check the amounts against the receipt.",
  "Cumpărături {store}": "Shopping {store}",
  "Cumpărături": "Shopping",
  "Poza nu s-a putut deschide.": "The photo couldn't be opened.",
  "Poza nu s-a putut pregăti.": "The photo couldn't be prepared.",
  "Nu am putut trimite poza. Verifică internetul și mai încearcă o dată.": "We couldn't send the photo. Check your internet connection and try again.",
  "(reducere −{amount})": "(discount −{amount})",
  "Am citit {count} produse, {total} în total.": "Read {count} products, {total} in total.",
  "Reduceri: −{amount}.": "Discounts: −{amount}.",
  "Verifică și apasă Salvează.": "Check them and tap Save.",
  "Spune ce a intrat": "Say what came in",
  "ex. „salariul, 4.700 de lei”": "e.g. “salary, 4,700 lei”",
  "Telefon": "Phone",
  "Conversația rămâne pe telefon. Dacă ghidul local n-a înțeles, pleacă la Google Gemini (sau Groq) întrebarea, ultimele mesaje și un rezumat al plicurilor. Ledul de sub robot arată cine a răspuns: verde Telefon, mov Gemini, negru Groq.": "The conversation stays on your phone. If the on-device guide doesn't understand, the question, the last messages and a summary of your envelopes go to Google Gemini (or Groq). The light under the robot shows who answered: green Phone, purple Gemini, black Groq.",
  "Calculele de mai sus se fac pe telefon. Sfaturile nu sunt consultanță financiară autorizată, nu sunt garantate și nu fac tranzacții.": "The calculations above run on your phone. The advice is not licensed financial advice, is not guaranteed and makes no transactions.",
  "Pe telefon": "On phone",
  "Consultantul folosește un serviciu AI (Google Gemini sau Groq). Pleacă doar un rezumat cu cifre: totaluri pe luni și categorii, plicuri, datorii, obiective. Nu pleacă mișcările, magazinele, notițele sau numele voastre.": "The consultant uses an AI service (Google Gemini or Groq). Only a summary of figures is sent: monthly and category totals, envelopes, debts, goals. Your transactions, stores, notes and names are not sent.",
  "Consultantul financiar": "Financial consultant",
  "Am înțeles, cere raportul": "Got it, get the report",
  "Consultantul nu a putut răspunde acum. Mai încearcă puțin mai târziu.": "The consultant couldn't answer right now. Try again a bit later.",
  "CONSULTANTUL FINANCIAR": "FINANCIAL CONSULTANT",
  "Cum stăm luna asta?": "How are we doing this month?",
  "raportul lunii trecute": "last month's report",
  "Urmăresc în continuare": "What I'll keep an eye on",
  "Raport din {date}. Sfaturile sunt orientative, nu consultanță autorizată.": "Report from {date}. The advice is a guide, not licensed financial advice.",
  "Actualizează": "Refresh",
  "Luna se apropie de final: raportul lunii e gata de cerut. Primești o evaluare sinceră și trei pași concreți, cu sume.": "The month is nearly over: this month's report is ready to ask for. You get an honest assessment and three concrete steps, with amounts.",
  "Primești o evaluare sinceră a lunii față de lunile trecute și trei pași concreți, cu sume în lei.": "You get an honest assessment of this month against previous months and three concrete steps, with amounts in lei.",
  "Notează mișcări câteva zile și consultantul va avea ce analiza.": "Log your spending for a few days and the consultant will have something to analyse.",
  "Consultantul analizează…": "The consultant is analysing…",
  "Cere raportul lunii": "Get this month's report",
  "Nu am putut ajunge la consultant. Verifică internetul și mai încearcă o dată.": "Couldn't reach the consultant. Check your internet connection and try again.",
  "Pe drumul bun": "On track",
  "Oprește": "Turn off",
  "SALVARE AUTOMATĂ": "AUTOMATIC BACKUP",
