  "Pornită, dar ultima salvare n-a mers: {reason}": "On, but the last save failed: {reason}",
  "Pornită · ultima salvare {time} · în Fișiere: Documente → Buget Familie → {file}": "On · last saved {time} · in Files: Documents → Buget Familie → {file}",
  "Un singur fișier în Documente/Buget Familie, rescris la câteva secunde după fiecare schimbare. Numele lui arată data și ora ultimei salvări (buget-familie-automat-AAAA-LL-ZZ-OOMM.json). Îl imporți oricând din Backup.": "A single file in Documents/Buget Familie, rewritten a few seconds after every change. Its name shows the date and time of the last save (buget-familie-automat-YYYY-MM-DD-HHMM.json). Import it anytime from Backup.",
  "Pornită · prima salvare în câteva secunde": "On · first save in a few seconds",
  "Citesc bonul din {count} capturi… {seconds} s": "Reading the receipt from {count} screenshots… {seconds}s",
  "Alege cel mult {count} capturi pentru un bon.": "Pick at most {count} screenshots for one receipt.",
  "Alege din galerie poza bonului sau mai multe capturi ale lui": "Pick the receipt photo or several screenshots of it from the gallery",
  "Din galerie: o poză sau mai multe capturi ale aceluiași bon": "From the gallery: one photo or several screenshots of the same receipt",
  "Bon lung? Pe hârtie: mai multe poze, una după alta. Digital: alege din galerie toate capturile.": "Long receipt? On paper: several photos, one after another. Digital: pick all screenshots from the gallery.",
  "Poza e gata. Bonul e lung? Fă și o poză cu partea următoare, apoi citește-le împreună.": "Photo ready. Long receipt? Take a photo of the next part too, then read them together.",
  "{count} poze ale aceluiași bon. Se citesc împreună, ca un singur bon.": "{count} photos of the same receipt. They are read together, as one receipt.",
