  "Anul acesta": "This year",
  "Voucherele de la automat le notezi ca venit (ex. „Voucher SGR”), pe sursa de tip voucher.": "Note the machine vouchers as income (e.g. \"SGR voucher\") on the voucher source.",
  "BON INCOMPLET": "INCOMPLETE RECEIPT",
