  "Suma rămasă nu dă totalul bonului, iar soldurile surselor nu mai sunt corecte.": "The remaining amount doesn't match the receipt total, so the source balances are off.",
  "Bon de {total}, în registru {kept}. Lipsesc {missing}{source}.": "Receipt of {total}, in the ledger {kept}. Missing {missing}{source}.",
  "din {source}": "from {source}",
