  "Șterse recent": "Recently removed",
  "Tot ce a ieșit din registru în ultimele 60 de zile, pe telefonul acesta: șters de tine, la o corectură sau la sincronizare. Pune înapoi ce nu trebuia să plece.": "Everything that left the ledger in the last 60 days on this phone: deleted by you, during a correction or by sync. Put back what shouldn't have gone.",
  "Bon {vendor}": "Receipt {vendor}",
  "{count} articole": "{count} items",
  "scos {when}": "removed {when}",
  "Pune înapoi": "Put back",
  "Pui înapoi „{label}” în registru?": "Put \"{label}\" back in the ledger?",
  "Golește lista": "Clear the list",
  "Potrivește soldul cu banii reali": "Match the balance to the real money",
  "CEVA NU SE POTRIVEȘTE?": "SOMETHING DOES NOT ADD UP?",
  "Potrivește soldul": "Match the balance",
  "Scrie câți bani ai de fapt. Diferența intră în Mișcări ca „Corecție de sold”, cu ziua de azi: soldul devine cel real, iar diferența nu apare ca cheltuială pe o categorie și nu strică analiza.": "Write how much you really have. The difference goes into Movements as a \"Balance correction\" dated today: the balance becomes the real one, and the difference doesn't show up as spending in a category or skew the analysis.",
  "Sursa": "Source",
  "în aplicație": "in the app",
  "Cât ai de fapt (lei)": "How much you really have (lei)",
  "Se potrivește deja.": "It already matches.",
  "Lipsesc {amount} față de aplicație: intră ca ieșire.": "{amount} missing compared to the app: it goes in as money out.",
  "Ai cu {amount} mai mult decât arată aplicația: intră ca intrare.": "You have {amount} more than the app shows: it goes in as money in.",
  "Potrivește": "Match",
  "Reamintirea de {when} nu a sosit: telefonul a oprit aplicația în fundal.": "The {when} reminder didn't arrive: the phone stopped the app in the background.",
  "Pe acest telefon, reamintirile pot întârzia sau lipsi dacă aplicația nu are voie să ruleze în fundal.": "On this phone, reminders can be late or missing if the app isn't allowed to run in the background.",
  "Pe {maker}: Setări → Baterie / Lansare aplicații → BonAI → Gestionare manuală, cu „Lansare automată” și „Rulare în fundal” pornite.": "On {maker}: Settings → Battery / App launch → BonAI → Manage manually, with \"Auto-launch\" and \"Run in background\" on.",
  "Setări → Aplicații → BonAI → Baterie → „Fără restricții”.": "Settings → Apps → BonAI → Battery → \"Unrestricted\".",
  "Deschide setarea": "Open the setting",
  "TELEFON CU APLICAȚIE VECHE": "PHONE WITH AN OLD APP",
  "Nu mai folosesc acel telefon": "I no longer use that phone",
  "Registrul de dinainte e păstrat în {path}.": "The previous ledger is kept in {path}.",
  "Actualizează aplicația pe celălalt telefon": "Update the app on the other phone",
  "{device}, văzut ultima dată {when}, are o versiune veche. Versiunile vechi pot șterge din greșeală o parte din bonurile plătite din două surse, iar ștergerea ajunge prin sincronizare și aici. Actualizează BonAI din Magazin Play pe acel telefon.": "{device}, last seen {when}, runs an old version. Old versions can mistakenly delete part of receipts paid from two sources, and the deletion reaches this phone through sync. Update BonAI from the Play Store on that phone.",
  "Bonul rămâne doar pe {source}, cu {amount}. Partea de {partAmount} din {partSource} se scoate din registru (o găsești în „Șterse recent”).": "The receipt stays only on {source}, with {amount}. The {partAmount} part from {partSource} leaves the ledger (you'll find it in \"Recently removed\").",
