  "Arată dacă banii ajung liniștit până la următorul venit: marja rămasă, plicurile în limită, scadențele din 7 zile și ritmul de cheltuire.": "Shows whether the money comfortably lasts until the next income: the margin left, envelopes within limits, bills due in the next 7 days and the spending pace.",
  "Peste 72 e calm, sub 45 e tensionat. Atinge cadranul pentru detalii.": "Above 72 is calm, below 45 is tense. Tap the dial for details.",
  "Scorul apare după ce notezi câteva zile. Atinge cadranul ca să vezi ce lipsește.": "The score appears after a few days of logging. Tap the dial to see what's missing.",
  "✓ Rândurile bat cu totalul bonului ({total}).": "✓ The lines match the receipt total ({total}).",
  "Lipsesc {diff} față de totalul bonului ({total}): rândurile fac {sum}. Poate un produs n-a fost citit.": "{diff} is missing from the receipt total ({total}): the lines add up to {sum}. An item may not have been read.",
  "Rândurile fac {sum}, cu {diff} peste totalul bonului ({total}). Verifică sumele sau o reducere necitită.": "The lines add up to {sum}, {diff} over the receipt total ({total}). Check the amounts or a discount that wasn't read.",
  "Diferență față de bon": "Difference from receipt",
