  "Fă o copie de siguranță": "Make a backup copy",
  "Ultima copie e de acum {days} zile. Dacă pierzi telefonul, registrul se pierde cu el: Mai mult → Setări → Copii de siguranță.": "Your last copy is {days} days old. If you lose your phone, the ledger goes with it: More → Settings → Backups.",
  "N-ai încă nicio copie a registrului. Dacă pierzi telefonul, se pierde și el: Mai mult → Setări → Copii de siguranță.": "You don't have a copy of the ledger yet. If you lose your phone, it's lost too: More → Settings → Backups.",
