  "Câteva plicuri care acoperă tot": "A few envelopes that cover everything",
  "Plătești cu orice card, bonuri sau cash: cheltuiala intră singură în plicul ei, fără „din plic sau din nerepartizat”. Cardul arată unde sunt banii, plicul arată pentru ce.": "Pay with any card, meal vouchers or cash: the expense lands in its envelope by itself, no \"from envelope or unallocated\" question. The card shows where the money is, the envelope shows what it's for.",
